// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = c.Owner();
        vm.deal(address(this), 2 ether);
        vm.prank(owner);
        // First, call multiplicate via Command to trigger the condition msg.value >= address(this).balance
        // The contract initially has 0 balance; we send 1 ether via Command, which triggers multiplicate’s if (since msg.value >= address(this).balance becomes 1 ether >= 0).
        c.Command{value: 1 ether}(address(0), abi.encodeWithSignature("multiplicate(address)", address(0x123)));
        // Now contract balance? After multiplicate, the balance is 0 because it transferred all to 0x123.
        // Let’s set up so there is a balance for withdraw: send some eth directly to contract.
        vm.deal(address(0x456), 5 ether);
        vm.prank(address(0x456));
        (bool sent,) = address(c).call{value: 5 ether}("");
        require(sent);
        // Now call withdraw as owner; buggy version sends to address(0), correct sends to owner.
        vm.prank(owner);
        c.withdraw();
        // After withdraw, in correct version, owner receives 5 ether; in buggy, address(0) receives it.
        assertTrue(owner.balance == 5 ether);
    }
}

