pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether
        vm.deal(address(c), 1 ether);

        // Call multiplicate with msg.value = 1 ether (>= contract balance)
        // This will transfer all contract balance (1+1=2 ether) to address(0) in multiplicate
        // But we only care about the state before withdraw
        vm.prank(address(0));
        c.multiplicate{value: 1 ether}(address(0));

        // Now contract balance is 0 (because multiplicate sent everything)
        // Let's fund contract again for withdraw
        vm.deal(address(c), 1 ether);

        // Owner calls withdraw
        address owner = c.Owner();
        uint256 ownerBalanceBefore = owner.balance;

        vm.prank(owner);
        c.withdraw();

        uint256 ownerBalanceAfter = owner.balance;
        // Reference: owner receives 1 ether, bug: owner receives nothing
        assertTrue(ownerBalanceAfter == ownerBalanceBefore + 1 ether);
    }
}

