pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = c.Owner();
        uint256 initialOwnerBalance = owner.balance;
        vm.deal(owner, 10 ether);
        vm.prank(owner);
        // Fund contract with 1 wei using Command (value 1, empty data)
        bytes memory emptyData = "";
        c.Command{value: 1}(address(0x01), emptyData);
        uint256 contractBalanceBeforeWithdraw = address(c).balance;
        assertTrue(contractBalanceBeforeWithdraw == 1);
        vm.prank(owner);
        c.withdraw();
        // In reference: owner.balance increases by 1 wei (the contract balance)
        // In buggy: owner.balance unchanged
        uint256 expectedDelta = 1; // the contract's entire balance
        assertTrue(owner.balance == initialOwnerBalance + expectedDelta);
    }
}

